import { parseBuiltinSpecifier } from './plugins.js';
export function generateWorkerEntry(pluginSpecifiers, sdkName, resolveImport = (specifier) => specifier, rpcServerProvider) {
    const imports = [];
    const registrations = [];
    let varIndex = 0;
    if (rpcServerProvider) {
        imports.push(`import { registerRpcServerProvider } from ${JSON.stringify(resolveImport(`${sdkName}/rpc-server-provider`))};`, `import rpcServerProvider from ${JSON.stringify(resolveImport(rpcServerProvider))};`);
        registrations.push('registerRpcServerProvider(rpcServerProvider);');
    }
    for (const specifier of pluginSpecifiers) {
        const builtin = parseBuiltinSpecifier(specifier, sdkName);
        if (builtin) {
            imports.push(`import { ${builtin.exportName} } from "${resolveImport(`${sdkName}/${builtin.suffix}/plugin`)}";`);
            registrations.push(`registerPlugin(${builtin.exportName});`);
        }
        else {
            const varName = `customPlugin${varIndex++}`;
            imports.push(`import ${varName} from "${resolveImport(specifier)}";`);
            registrations.push(`registerPlugin(${varName});`);
        }
    }
    const importsStr = imports.join('\n');
    const registrationsStr = registrations.join('\n');
    const pluginsList = pluginSpecifiers.map((p) => `*   - ${p}`).join('\n');
    return `/**
 * QVAC SDK Worker Entry (auto-generated)
 * Generated by: @qvac/sdk/commands bundleSdk
 * Plugins: ${pluginSpecifiers.length}
 *
${pluginsList}
 */

import { initializeWorker, ensureRPCSetup } from "${resolveImport(`${sdkName}/worker-lifecycle`)}";
import { registerPlugin } from "${resolveImport(`${sdkName}/plugins`)}";
import { getServerLogger } from "${resolveImport(`${sdkName}/logging`)}";

${importsStr}

const { hasRPCConfig } = initializeWorker();

const logger = getServerLogger();
logger.info("🐻 QVAC Worker (custom bundle)");
logger.info("📦 Plugins: ${pluginSpecifiers.length}");

${registrationsStr}

// Auto-setup RPC if config present
if (hasRPCConfig) {
  ensureRPCSetup();
}
`;
}
export function generateWorkerEntries(pluginSpecifiers, sdkName, resolveBundleImport, rpcServerProvider) {
    return {
        runtimeEntry: generateWorkerEntry(pluginSpecifiers, sdkName, undefined, rpcServerProvider),
        bundleEntry: generateWorkerEntry(pluginSpecifiers, sdkName, resolveBundleImport, rpcServerProvider)
    };
}
